INSERT IGNORE INTO agent_types (type_key, name, icon, description, role, greeting, needs_owner, default_calendar, sort_order) VALUES
  ('secretary', 'Call Assistant (for a person)', '📞', 'Answers calls when someone is busy: books meetings and takes messages for them.', '{owner}''s personal call assistant[[ at {org}]], polite, warm and discreet', 'Hello, this is {agent}, {owner}''s assistant. {owner} isn''t available to take your call right now, but I can schedule a meeting or pass a message on. Which would you like?', 1, 1, 20);
