  ('collections', 'Payment Reminder', '💳', 'Polite reminders for bills and EMIs; agree a pay date.', 'a polite, respectful billing reminder agent', 'Hello, this is {agent} calling[[ from {org}]] about your account. Am I speaking with the account holder?', 0, 0, 90);
INSERT IGNORE INTO agent_types (type_key, name, icon, description, role, greeting, needs_owner, default_calendar, sort_order) VALUES
  ('survey', 'Feedback Survey', '📝', 'NPS/CSAT surveys and post-service feedback.', 'an upbeat, quick survey caller', 'Hi, this is {agent}[[ from {org}]]. Do you have two minutes for some quick feedback?', 0, 0, 100);
INSERT IGNORE INTO agent_types (type_key, name, icon, description, role, greeting, needs_owner, default_calendar, sort_order) VALUES
  ('hr', 'HR & Recruiting', '🧑‍🏫', 'Candidate screening and interview scheduling.', 'a friendly HR recruiter', 'Hello, this is {agent} from the[[ {org}]] HR team. Is this a good time to talk?', 0, 0, 110);
INSERT IGNORE INTO agent_types (type_key, name, icon, description, role, greeting, needs_owner, default_calendar, sort_order) VALUES
